import bcrypt from "bcryptjs";
import { runAutomation } from "./automation.js";

const TYPES={1:"香港",5:"澳门",8:"天天"},SECTIONS={yixiao:"平特一肖",erxiao:"平特二肖",sanxiao:"平特三肖",liuxiao:"平特一肖",tema:"五期必中·特码",weishu:"平特尾数",sanzhongsan:"三中三",erzhonger:"二中二",chengyu:"成语解肖"};
const AD_POSITIONS={popup:"首页弹窗广告",...Object.fromEntries(Array.from({length:9},(_,i)=>[`home-${i+1}`,`首页横幅广告位 ${i+1}`])),list:"列表页广告位",detail:"内容页广告位"};
const enc=new TextEncoder(),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const now=()=>new Date().toISOString().slice(0,19).replace("T"," ");
const redirect=(to,headers={})=>new Response(null,{status:303,headers:{location:to,...headers}});
async function mac(secret,value){const key=await crypto.subtle.importKey("raw",enc.encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]),sig=await crypto.subtle.sign("HMAC",key,enc.encode(value));return btoa(String.fromCharCode(...new Uint8Array(sig))).replace(/=+$/g,"").replace(/\+/g,"-").replace(/\//g,"_");}
async function session(request,env){const raw=(request.headers.get("cookie")||"").match(/(?:^|;\s*)cf_admin=([^;]+)/)?.[1];if(!raw)return null;const [id,exp,csrf,sig]=raw.split(".");if(!id||Number(exp)<Date.now()/1000||await mac(env.SESSION_SECRET,`${id}.${exp}.${csrf}`)!==sig)return null;return {id:Number(id),csrf};}
async function cookie(env,id){const exp=Math.floor(Date.now()/1000)+1800,csrf=crypto.randomUUID().replaceAll("-","");const base=`${id}.${exp}.${csrf}`,sig=await mac(env.SESSION_SECRET,base);return {value:`cf_admin=${base}.${sig}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=1800`,csrf};}
function shell(title,body){return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>*{box-sizing:border-box}body{margin:0;background:#0d0d0d;color:#eee;font:14px system-ui}.top{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:14px 4%;background:#171717;border-bottom:1px solid #39301b}.top a{color:#edcc64;margin-left:12px}.wrap{max-width:1180px;margin:auto;padding:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.card{background:#171717;border:1px solid #353128;border-radius:9px;padding:16px}.wide{grid-column:1/-1}h1,h2{margin-top:0;color:#f0ce68}label{display:grid;gap:5px;margin:9px 0}input,select,textarea,button{font:inherit;border-radius:6px;border:1px solid #4a4333;background:#101010;color:#eee;padding:9px}textarea{min-height:82px}button{cursor:pointer;background:#6d5418;color:#fff1b5;font-weight:700}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:9px;border-bottom:1px solid #2c2c2c;text-align:left}.scroll{overflow:auto}.actions{display:flex;gap:6px}.actions button{padding:6px}.danger{background:#681f1f}.ok{color:#69dc88}.bad{color:#ff7676}.muted{color:#999}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.stats b{font-size:23px;color:#f0ce68}.login{max-width:390px;margin:12vh auto}.notice{padding:10px;background:#21381f;border-radius:6px}@media(max-width:760px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}.top{align-items:flex-start}.top nav{display:grid;gap:4px}}</style></head><body>${body}</body></html>`;}
function csrfInput(s){return `<input type="hidden" name="csrf" value="${esc(s.csrf)}">`;}
function nav(){return `<nav><a href="/admin/">资料</a><a href="/admin/ads">广告</a><a href="/admin/links">网站推荐</a><a href="/admin/analytics">统计</a><a href="/admin/export">导出</a><a href="/admin/logout">退出</a></nav>`;}
async function ensureSiteLinks(db){await db.prepare("CREATE TABLE IF NOT EXISTS site_links(slot INTEGER PRIMARY KEY,label TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP)").run();const defaults=[[1,"123六合网","https://123lh.668870.cc/"],[2,"六合王","https://lhw.235-from.com/"],[3,"跑狗论坛","https://paogt06.h6sdeg6.com/"],[4,"更多网站",""]];await db.batch(defaults.map(([slot,label,url])=>db.prepare("INSERT OR IGNORE INTO site_links(slot,label,url,enabled) VALUES(?,?,?,1)").bind(slot,label,url)));}
export async function handleAdmin(request,env){
  const url=new URL(request.url),s=await session(request,env);
  if(url.pathname==="/admin/login")return login(request,env,s);
  if(url.pathname==="/admin/logout")return redirect("/admin/login",{"set-cookie":"cf_admin=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Strict"});
  if(!s)return redirect("/admin/login");
  if(request.method==="POST"){const form=await request.formData();if(form.get("csrf")!==s.csrf)return new Response("页面已过期",{status:419});return action(url.pathname,form,env);}
  if(url.pathname==="/admin"||url.pathname==="/admin/")return dashboard(url,env,s);
  if(url.pathname==="/admin/ads")return ads(env,s);
  if(url.pathname==="/admin/links")return links(env,s);
  if(url.pathname==="/admin/analytics")return analytics(env,s);
  if(url.pathname==="/admin/export")return exportCsv(env.DB);
  return new Response("Not found",{status:404});
}
async function login(request,env,s){if(s)return redirect("/admin/");let error="";if(request.method==="POST"){const f=await request.formData(),u=String(f.get("username")||""),p=String(f.get("password")||""),row=await env.DB.prepare("SELECT id,password_hash FROM admins WHERE username=? LIMIT 1").bind(u).first(),hash=String(row?.password_hash||"").replace(/^\$2y\$/,"$2b$");if(row&&await bcrypt.compare(p,hash)){const c=await cookie(env,row.id);return redirect("/admin/",{"set-cookie":c.value});}error="账号或密码错误";}return new Response(shell("后台登录",`<main class="login card"><h1>Cloudflare 资料后台</h1>${error?`<p class="bad">${error}</p>`:""}<form method="post"><label>账号<input name="username" required></label><label>密码<input name="password" type="password" required></label><button>登录</button></form></main>`),{headers:{"content-type":"text/html;charset=utf-8"}});}
async function dashboard(url,env,s){const page=Math.max(1,Number(url.searchParams.get("page")||1)),offset=(page-1)*30,{results=[]}=await env.DB.prepare("SELECT * FROM materials ORDER BY id DESC LIMIT 30 OFFSET ?").bind(offset).all(),runs=(await env.DB.prepare("SELECT * FROM automation_runs ORDER BY id DESC LIMIT 5").all()).results||[];const rows=results.map(r=>`<tr><td>${TYPES[r.lottery_type]||r.lottery_type}</td><td>${SECTIONS[r.section_key]||r.section_key}</td><td>${esc(r.source_name)}</td><td>${esc(r.period)}</td><td>${esc(r.content)}</td><td class="${r.hit_status==='hit'?'ok':r.hit_status==='miss'?'bad':''}">${esc(r.hit_status)}</td><td><div class="actions"><form method="post" action="/admin/toggle">${csrfInput(s)}<input type="hidden" name="id" value="${r.id}"><input type="hidden" name="published" value="${r.published?0:1}"><button>${r.published?'隐藏':'显示'}</button></form><form method="post" action="/admin/delete" onsubmit="return confirm('确定删除？')">${csrfInput(s)}<input type="hidden" name="id" value="${r.id}"><button class="danger">删除</button></form></div></td></tr>`).join("");const runRows=runs.map(r=>`<tr><td>${esc(r.task_key)}</td><td>${esc(r.started_at)}</td><td class="${r.status==='success'?'ok':'bad'}">${esc(r.status)}</td><td>${esc(r.error_message||"")}</td></tr>`).join("");return html(shell("资料后台",`<header class="top"><strong>Cloudflare 资料后台</strong>${nav()}</header><main class="wrap"><div class="grid"><section class="card"><h2>发布新资料</h2><form method="post" action="/admin/save">${csrfInput(s)}<label>彩种<select name="lottery_type">${Object.entries(TYPES).map(([k,v])=>`<option value="${k}">${v}</option>`).join("")}</select></label><label>栏目<select name="section_key">${Object.entries(SECTIONS).map(([k,v])=>`<option value="${k}">${v}</option>`).join("")}</select></label><label>名称<input name="source_name" required></label><label>期号<input name="period" inputmode="numeric" required></label><label>内容<textarea name="content" required></textarea></label><label>结果<select name="hit_status"><option value="pending">待开奖</option><option value="hit">命中</option><option value="miss">未中</option></select></label><button>保存并发布</button></form></section><section class="card"><h2>自动任务</h2><p>Cloudflare 每小时第 10 分钟自动执行。</p><form method="post" action="/admin/run-auto">${csrfInput(s)}<button>立即更新全部资料</button></form><div class="scroll"><table>${runRows}</table></div></section><section class="card wide"><h2>资料列表</h2><div class="scroll"><table><thead><tr><th>彩种</th><th>栏目</th><th>名称</th><th>期号</th><th>内容</th><th>结果</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div><p><a href="/admin/?page=${Math.max(1,page-1)}">上一页</a>　第 ${page} 页　<a href="/admin/?page=${page+1}">下一页</a></p></section></div></main>`));}
async function action(path,f,env){const db=env.DB;if(path==="/admin/save"){const type=Number(f.get("lottery_type")),section=String(f.get("section_key")),name=String(f.get("source_name")||"").trim(),period=String(f.get("period")||"").trim(),content=String(f.get("content")||"").trim(),status=String(f.get("hit_status")||"pending");if(!TYPES[type]||!SECTIONS[section]||!name||!/^\d{1,10}$/.test(period)||!content)return new Response("资料填写不完整",{status:422});await db.prepare("INSERT INTO materials(lottery_type,section_key,source_name,period,content,hit_status,published,created_at,updated_at) VALUES(?,?,?,?,?,?,1,?,?) ON CONFLICT(lottery_type,section_key,source_name,period) DO UPDATE SET content=excluded.content,hit_status=excluded.hit_status,published=1,updated_at=excluded.updated_at").bind(type,section,name,period,content,status,now(),now()).run();}
  else if(path==="/admin/toggle")await db.prepare("UPDATE materials SET published=? WHERE id=?").bind(Number(f.get("published")),Number(f.get("id"))).run();
  else if(path==="/admin/delete")await db.prepare("DELETE FROM materials WHERE id=?").bind(Number(f.get("id"))).run();
  else if(path==="/admin/run-auto"){await runAutomation(db);}
  else if(path==="/admin/save-link"){await ensureSiteLinks(db);const slot=Number(f.get("slot")||0),label=String(f.get("label")||"").trim().slice(0,30),url=String(f.get("url")||"").trim().slice(0,500),enabled=Number(f.get("enabled")||0);if(!label)return new Response("网站名称不能为空",{status:422});if(url&&!/^https:\/\//i.test(url))return new Response("跳转链接必须以 https:// 开头",{status:422});if(slot>0)await db.prepare("UPDATE site_links SET label=?,url=?,enabled=?,updated_at=? WHERE slot=?").bind(label,url,enabled,now(),slot).run();else await db.prepare("INSERT INTO site_links(slot,label,url,enabled,updated_at) SELECT COALESCE(MAX(slot),0)+1,?,?,?,? FROM site_links").bind(label,url,enabled,now()).run();return redirect("/admin/links?saved=1");}
  else if(path==="/admin/delete-link"){await ensureSiteLinks(db);const slot=Number(f.get("slot")||0);if(slot>0)await db.prepare("DELETE FROM site_links WHERE slot=?").bind(slot).run();return redirect("/admin/links?deleted=1");}
  else if(path==="/admin/save-ad"){let imagePath=String(f.get("image_path")||""),file=f.get("image_file"),position=String(f.get("position_key"));if(file instanceof File&&file.size){if(file.size>5*1024*1024)return new Response("图片不能超过 5MB",{status:422});if(!["image/jpeg","image/png","image/webp","image/gif"].includes(file.type))return new Response("只允许 JPG、PNG、WebP、GIF",{status:422});const ext={"image/jpeg":"jpg","image/png":"png","image/webp":"webp","image/gif":"gif"}[file.type],key=`cf-assets/ads/${position}-${crypto.randomUUID()}.${ext}`;await env.ASSETS_KV.put(key,await file.arrayBuffer(),{metadata:{contentType:file.type}});imagePath=`/${key}`;}await db.prepare("UPDATE ads SET image_path=?,link_url=?,enabled=?,display_mode=?,delay_seconds=?,start_at=?,end_at=?,updated_at=? WHERE position_key=?").bind(imagePath,String(f.get("link_url")||""),Number(f.get("enabled")||0),String(f.get("display_mode")||"daily"),Number(f.get("delay_seconds")||1),String(f.get("start_at")||"")||null,String(f.get("end_at")||"")||null,now(),position).run();return redirect("/admin/ads");}
  return redirect("/admin/");}
async function ads(env,s){await env.DB.batch(Object.keys(AD_POSITIONS).map(key=>env.DB.prepare("INSERT OR IGNORE INTO ads(position_key) VALUES(?)").bind(key)));const rows=(await env.DB.prepare("SELECT a.*,COALESCE(s.impressions,0) impressions,COALESCE(s.total_clicks,0) clicks FROM ads a LEFT JOIN ad_stats s USING(position_key) ORDER BY CASE WHEN a.position_key='popup' THEN 0 WHEN a.position_key LIKE 'home-%' THEN CAST(substr(a.position_key,6) AS INTEGER) ELSE 20 END,a.position_key").all()).results||[];return html(shell("广告管理",`<header class="top"><strong>广告管理</strong>${nav()}</header><main class="wrap"><p class="notice">首页共有 9 个横幅广告位，另外包含弹窗、列表页和内容页广告位。</p><div class="grid">${rows.map(r=>`<section class="card"><h2>${esc(AD_POSITIONS[r.position_key]||r.position_key)}</h2><p class="muted">位置编号：${esc(r.position_key)}　展示 ${r.impressions}　点击 ${r.clicks}</p><form method="post" action="/admin/save-ad" enctype="multipart/form-data">${csrfInput(s)}<input type="hidden" name="position_key" value="${esc(r.position_key)}"><input type="hidden" name="image_path" value="${esc(r.image_path)}">${r.image_path?`<img src="${esc(r.image_path)}" alt="" style="max-width:100%;max-height:120px">`:""}<label>上传新图片（最大 5MB）<input type="file" name="image_file" accept="image/jpeg,image/png,image/webp,image/gif"></label><label>跳转链接<input name="link_url" value="${esc(r.link_url)}"></label><label>显示方式<select name="display_mode"><option value="daily" ${r.display_mode==='daily'?'selected':''}>每天一次</option><option value="always" ${r.display_mode==='always'?'selected':''}>每次显示</option></select></label><label>延迟秒数<input name="delay_seconds" type="number" value="${r.delay_seconds}"></label><label><input name="enabled" type="checkbox" value="1" ${r.enabled?'checked':''}> 启用</label><button>保存</button></form></section>`).join("")}</div></main>`));}
async function links(env,s){await ensureSiteLinks(env.DB);const rows=(await env.DB.prepare("SELECT * FROM site_links ORDER BY slot").all()).results||[];return html(shell("网站推荐管理",`<header class="top"><strong>网站推荐管理</strong>${nav()}</header><main class="wrap"><p class="notice">推荐网站数量不限，可随时新增。这里只维护一套链接；前台标题会随彩种自动变化。</p><section class="card"><h2>新增推荐网站</h2><form method="post" action="/admin/save-link">${csrfInput(s)}<label>网站名称<input name="label" required placeholder="网站名称"></label><label>跳转链接<input name="url" placeholder="https://"></label><label><input type="checkbox" name="enabled" value="1" checked> 添加后立即显示</label><button>新增网站</button></form></section><div class="grid" style="margin-top:14px">${rows.map(r=>`<section class="card"><h2>${esc(r.label)}</h2><form method="post" action="/admin/save-link">${csrfInput(s)}<input type="hidden" name="slot" value="${r.slot}"><label>网站名称<input name="label" value="${esc(r.label)}" required></label><label>跳转链接<input name="url" value="${esc(r.url)}" placeholder="https://"></label><label><input type="checkbox" name="enabled" value="1" ${r.enabled?'checked':''}> 前台显示</label><button>保存修改</button></form><form method="post" action="/admin/delete-link" onsubmit="return confirm('确定删除这个推荐网站吗？')" style="margin-top:8px">${csrfInput(s)}<input type="hidden" name="slot" value="${r.slot}"><button class="danger">删除</button></form></section>`).join("")}</div></main>`));}
async function analytics(env,s){const total=await env.DB.prepare("SELECT COALESCE(SUM(views),0) n FROM analytics_daily").first(),uv=await env.DB.prepare("SELECT COUNT(*) n FROM analytics_visitors").first(),today=await env.DB.prepare("SELECT COALESCE(SUM(views),0) n FROM analytics_daily WHERE visit_date=date('now')").first(),visitors=(await env.DB.prepare("SELECT * FROM analytics_visitors ORDER BY last_seen DESC LIMIT 100").all()).results||[];return html(shell("访问统计",`<header class="top"><strong>访问统计</strong>${nav()}</header><main class="wrap"><section class="stats"><article class="card">累计访问<br><b>${total.n}</b></article><article class="card">独立 IP<br><b>${uv.n}</b></article><article class="card">今日访问<br><b>${today.n}</b></article></section><section class="card"><h2>最近访客</h2><div class="scroll"><table><tr><th>IP</th><th>国家</th><th>地区</th><th>城市</th><th>次数</th><th>最后访问</th></tr>${visitors.map(v=>`<tr><td>${esc(v.ip_address)}</td><td>${esc(v.country)}</td><td>${esc(v.region_name)}</td><td>${esc(v.city)}</td><td>${v.views}</td><td>${esc(v.last_seen)}</td></tr>`).join("")}</table></div></section></main>`));}
async function exportCsv(db){const rows=(await db.prepare("SELECT ip_address,country,region_name,city,views,first_seen,last_seen FROM analytics_visitors ORDER BY last_seen DESC").all()).results||[],q=v=>`"${String(v??"").replaceAll('"','""')}"`,csv="\ufeffIP,国家,省份/州,城市,访问次数,首次访问时间,最后访问时间\n"+rows.map(r=>[r.ip_address,r.country,r.region_name,r.city,r.views,r.first_seen,r.last_seen].map(q).join(",")).join("\n");return new Response(csv,{headers:{"content-type":"text/csv;charset=utf-8","content-disposition":"attachment; filename=visitor-statistics.csv"}});}
const html=body=>new Response(body,{headers:{"content-type":"text/html;charset=utf-8","cache-control":"no-store","x-frame-options":"SAMEORIGIN","content-security-policy":"frame-ancestors 'self'; object-src 'none'; base-uri 'self'; form-action 'self'"}});
